// MosaicPlatformEffects.swift -- the operating-system capabilities Mosaic
// provides on SwiftUI, shared by every generated app (UI87 §7).
//
// Generated by mosaic-app-bindings; do not edit in a generated project. An app
// that needs different behaviour for a standard kind claims that kind in its
// own `[host_effects]` handler instead (UI87 §7.2).
//
// What it answers
// ---------------
//
//   files.open  { accept: [MIME...] }
//               -> ok { name, mimeType, bytes (base64) } | cancelled {} | failed { message }
//   files.save  { suggestedName, accept: [MIME...], bytes (base64) }
//               -> ok { name } | cancelled {} | failed { message }
//
// These are UI59's and UI87's contracts, answered exactly as the Compose
// library answers them. A name is returned, never a path: a path would tell
// the app (and anything it logs) where the person keeps files.
//
// Per operating system
// --------------------
//
//   macOS ........ NSOpenPanel / NSSavePanel, the system's own panels
//   iOS, iPadOS .. not yet (UI89 step 6 brings UIDocumentPickerViewController);
//                  each request fails with a message, so an Await never wedges
//
// Routing
// -------
//
// The generated App.swift installs the app's own handler first, then this,
// which wraps it. Each effect is routed by kind:
//
//   kind the app claims ........ the app's handler
//   files.open / files.save .... this library
//   anything else .............. the app's handler if it claimed nothing
//                                (the original meaning), otherwise nobody --
//                                and the host fails an unanswered Await
//                                rather than leaving it pending.
//
// Threading
// ---------
//
// The host's lock is held while a handler runs, so a modal panel shown inline
// would hold it for as long as the panel is open -- and SwiftUI calls
// `applyProps()` every frame. Each standard effect is DEFERRED, then answered
// from the main queue, which is also where AppKit panels must run. Nothing may
// escape that block: once deferred, an effect is out of the host's fail
// sweep, so a lost answer would leave it awaited for the life of the process.

import Foundation
#if os(macOS)
import AppKit
import UniformTypeIdentifiers
#endif

/// The effect kinds this library answers unless an app claims them.
let mosaicStandardEffectKinds: Set<String> = ["files.open", "files.save"]

/// The largest file `files.open` reads (UI59 parity with Qt, XAML, Compose).
let mosaicMaxOpenBytes = 50 * 1024 * 1024

/// The largest payload `files.save` writes (UI87 §3.1).
let mosaicMaxSaveBytes = 16 * 1024 * 1024

/// What the router needs from a host. `MosaicRuntimeHost` is the real one; a
/// test supplies a fake, so routing and deferral run without a Rust runtime.
protocol MosaicPlatformEffectHost: AnyObject {
  var effectHandler: ((UInt64, String, Any, String) -> Void)? { get set }
  func deferEffect(_ id: UInt64) -> Bool
  func completeEffect(_ id: UInt64, _ result: [String: Any]) -> NSDictionary?
}

extension MosaicRuntimeHost: MosaicPlatformEffectHost {}

/// The two panels, behind a protocol so a test can answer them without a
/// display. Each returns the chosen file, or nil when the person cancelled.
protocol MosaicFileDialogs {
  func chooseFileToOpen(extensions: [String]) -> URL?
  func chooseFileToSave(suggestedName: String, extensions: [String]) -> URL?
}

/// The platform's own panels. On iOS and iPadOS there are none yet (UI89
/// step 6), and every request fails with a message rather than waiting.
struct MosaicSystemFileDialogs: MosaicFileDialogs {
  func chooseFileToOpen(extensions: [String]) -> URL? {
    #if os(macOS)
    let panel = NSOpenPanel()
    panel.canChooseFiles = true
    panel.canChooseDirectories = false
    panel.allowsMultipleSelection = false
    let types = extensions.compactMap { UTType(filenameExtension: $0) }
    if !types.isEmpty { panel.allowedContentTypes = types }
    // Images only: open in Pictures, as a photo picker should. Anything else
    // keeps the panel's own default start.
    if mosaicOnlyImages(extensions),
      let pictures = FileManager.default.urls(for: .picturesDirectory, in: .userDomainMask).first
    {
      panel.directoryURL = pictures
    }
    return panel.runModal() == .OK ? panel.url : nil
    #else
    return nil
    #endif
  }

  func chooseFileToSave(suggestedName: String, extensions: [String]) -> URL? {
    #if os(macOS)
    let panel = NSSavePanel()
    panel.nameFieldStringValue = suggestedName
    let types = extensions.compactMap { UTType(filenameExtension: $0) }
    if !types.isEmpty { panel.allowedContentTypes = types }
    return panel.runModal() == .OK ? panel.url : nil
    #else
    return nil
    #endif
  }
}

/// True where this library has panels to show. Elsewhere a standard kind
/// fails at once, with a message, instead of reporting a cancel nobody made.
let mosaicPlatformHasFileDialogs: Bool = {
  #if os(macOS)
  return true
  #else
  return false
  #endif
}()

// The MIME types an app names, and the extensions a panel filters on. A type
// this table does not know is dropped rather than failing the request (UI59
// §3). The same table as the Compose library, so both hosts agree.
private let mosaicMimeExtensions: [(mime: String, extensions: [String])] = [
  ("application/json", ["json"]),
  ("text/plain", ["txt"]),
  ("text/markdown", ["md", "markdown"]),
  ("text/csv", ["csv"]),
  ("application/pdf", ["pdf"]),
  ("application/zip", ["zip"]),
  ("image/jpeg", ["jpg", "jpeg"]),
  ("image/png", ["png"]),
  ("image/webp", ["webp"]),
  ("image/gif", ["gif"]),
  ("image/bmp", ["bmp"]),
  ("image/tiff", ["tif", "tiff"]),
  ("image/svg+xml", ["svg"]),
]

func mosaicMimeType(for url: URL) -> String {
  let fileExtension = url.pathExtension.lowercased()
  return mosaicMimeExtensions.first { $0.extensions.contains(fileExtension) }?.mime
    ?? "application/octet-stream"
}

/// Whether every extension the open panel filters on is an image's, so it can
/// start in the Pictures folder (UI59 §2: a caller that wants "pictures only"
/// accepts image types, and the panel's start location follows). No filter at
/// all is not "only images": it means any file, and the panel starts where it
/// always has. The same rule as the XAML, Qt and Compose libraries.
///
///     accept                         extensions        start
///     ["image/png", "image/jpeg"]    png jpg jpeg      Pictures
///     ["image/png", "text/plain"]    png txt           the panel's default
///     []                             (none)            the panel's default
func mosaicOnlyImages(_ extensions: [String]) -> Bool {
  guard !extensions.isEmpty else { return false }
  return extensions.allSatisfy { fileExtension in
    mosaicMimeExtensions.contains { row in
      row.mime.hasPrefix("image/") && row.extensions.contains(fileExtension)
    }
  }
}

private func mosaicPayloadDictionary(_ payload: Any) -> [String: Any] {
  (payload as? [String: Any]) ?? [:]
}

func mosaicExtensions(for payload: [String: Any]) -> [String] {
  let accepted = (payload["accept"] as? [Any] ?? []).compactMap { $0 as? String }
  var seen: [String] = []
  for mime in accepted {
    for fileExtension in mosaicMimeExtensions.first(where: { $0.mime == mime })?.extensions ?? []
    where !seen.contains(fileExtension) {
      seen.append(fileExtension)
    }
  }
  return seen
}

private func mosaicOk(_ value: [String: Any]) -> [String: Any] { ["ok": value] }
private func mosaicCancelled() -> [String: Any] { ["cancelled": [String: Any]()] }
func mosaicFailed(_ message: String) -> [String: Any] { ["failed": ["message": message]] }

/// What reading the chosen file came to.
enum MosaicOpenRead {
  case bytes(Data)
  case notRegular
  case tooLarge
  case unreadable
}

/// Open the chosen file ONCE and decide everything from that descriptor.
///
/// - The type check is `fstat` on the open descriptor, not a separate lookup
///   by path: a path checked and then opened can be swapped in between, and a
///   FIFO swapped in would block the main queue for ever.
/// - `O_NONBLOCK` makes even that open return at once on a FIFO; a regular
///   file ignores the flag, so reads behave normally.
/// - A symlink the person chose is resolved once, here; the open then uses
///   `O_NOFOLLOW`, so a link swapped in after that is refused, not followed.
/// - Bounded while reading, not by checking the size first: a file can grow
///   between a check and a read, which is the TOCTOU the XAML handler's review
///   found (#15218).
func mosaicReadChosenFile(_ url: URL, limit: Int) -> MosaicOpenRead {
  let descriptor = open(url.resolvingSymlinksInPath().path, O_RDONLY | O_NONBLOCK | O_NOFOLLOW)
  guard descriptor >= 0 else { return .unreadable }
  let handle = FileHandle(fileDescriptor: descriptor, closeOnDealloc: true)
  var info = stat()
  guard fstat(descriptor, &info) == 0 else { return .unreadable }
  guard (info.st_mode & S_IFMT) == S_IFREG else { return .notRegular }
  var out = Data()
  do {
    while true {
      guard let chunk = try handle.read(upToCount: 64 * 1024), !chunk.isEmpty else {
        return .bytes(out)
      }
      if out.count + chunk.count > limit { return .tooLarge }
      out.append(chunk)
    }
  } catch {
    return .unreadable
  }
}

/// A suggested name is a plain file name (UI87 §3.1), so an app cannot steer
/// the panel, or disguise what it is saving -- the same rule as the Compose
/// library:
///
/// - no directory separators, and not `.` or `..` -- no other directory;
/// - no leading `.` -- a hidden dot-file such as `.zshrc` is configuration a
///   shell or tool runs, not a document;
/// - no `:` -- the Finder shows it as `/`, and on Windows it names a drive or
///   an alternate data stream;
/// - no control, format, line- or paragraph-separator characters -- a
///   right-to-left override can make `invoice<RLO>fdp.exe` read as a PDF in
///   the panel, and a separator breaks the name across lines;
/// - no leading or trailing whitespace of any kind (a no-break space
///   included), no run of two or more whitespace characters, and no trailing
///   dot -- `report.pdf` padded out and ending `.command` hides its extension;
/// - at most 255 UTF-16 units, the same count the Compose library makes.
func mosaicIsPlainFileName(_ name: String) -> Bool {
  guard !name.isEmpty, name.utf16.count <= 255, name != ".", name != ".." else {
    return false
  }
  // By SCALAR throughout, never by Character: a Character is a grapheme
  // cluster, and a Prepend letter (U+0D4E) or a combining mark (U+0301)
  // merges with a neighbouring `.` into one, so `hasPrefix(".")` and
  // `lastIndex(of: ".")` would not see it -- while the file system, and the
  // Compose and browser hosts, do.
  let scalars = name.unicodeScalars
  let refused = scalars.contains { scalar in
    if scalar == "/" || scalar == "\\" || scalar == ":" { return true }
    switch scalar.properties.generalCategory {
    case .control, .format, .lineSeparator, .paragraphSeparator,
      // Unassigned and private-use code points mean different things to
      // different runtimes' Unicode tables (Swift strings hold no surrogates).
      .unassigned, .privateUse, .surrogate:
      return true
    default: return false
    }
  }
  if refused { return false }
  // The padding and dot rules look at what is visible: invisible characters
  // cannot split a run of spaces or hide a leading or trailing dot.
  let visible = scalars.filter { !mosaicIsInvisible($0) }
  guard let first = visible.first, let last = visible.last,
    first != ".", last != ".",
    !mosaicIsSpace(first), !mosaicIsSpace(last)
  else {
    return false
  }
  var previousWasSpace = false
  for scalar in visible {
    let isSpace = mosaicIsSpace(scalar)
    if isSpace && previousWasSpace { return false }
    previousWasSpace = isSpace
  }
  return true
}

/// Characters that are not whitespace to Unicode but render as a wide blank:
/// the Hangul fillers and BRAILLE PATTERN BLANK. Whitespace for the padding
/// rules, as on the other hosts.
private let mosaicBlankCharacters: Set<UInt32> = [0x115F, 0x1160, 0x2800, 0x3164, 0xFFA0]

private func mosaicIsSpace(_ scalar: Unicode.Scalar) -> Bool {
  scalar.properties.isWhitespace || mosaicBlankCharacters.contains(scalar.value)
}

/// Default-ignorable characters other than the blanks: variation selectors,
/// COMBINING GRAPHEME JOINER and the like. Dropped before the padding and dot
/// rules, so `<space><VS1><space>` is still a run while an emoji's own
/// selector (`❤️ list.txt`) is fine.
private func mosaicIsInvisible(_ scalar: Unicode.Scalar) -> Bool {
  scalar.properties.isDefaultIgnorableCodePoint && !mosaicBlankCharacters.contains(scalar.value)
}

/// The extension after the last `.`, found by scalar (see
/// `mosaicIsPlainFileName`) and folded through upper case, so `ſ` (LONG S)
/// compares as `s`; nil when there is no dot.
func mosaicFileExtension(_ name: String) -> String? {
  let scalars = name.unicodeScalars
  guard let dot = scalars.lastIndex(of: ".") else { return nil }
  return String(scalars[scalars.index(after: dot)...]).uppercased().lowercased()
}

/// Extensions that run when the file is opened, on some platform: when an
/// app names no type (`accept` empty) a save may not end in one of these, so
/// a `files.save` cannot drop a launcher next to the person's documents. When
/// the app does name types, the name must already end in one of theirs. The
/// same set as the Compose library.
let mosaicExecutableExtensions: Set<String> = [
  // macOS: Terminal scripts, Finder location files and installers open
  // with no prompt, or install.
  "command", "terminal", "tool", "webloc", "inetloc", "fileloc", "afploc", "ftploc",
  "mailloc", "newsloc", "atloc", "app", "pkg", "mpkg", "dmg", "mobileconfig", "scpt",
  "applescript", "workflow",
  // Windows: run, install, or leak credentials when merely browsed.
  "exe", "com", "bat", "cmd", "scr", "pif", "msi", "msp", "msc", "lnk", "url", "hta",
  "cpl", "chm", "inf", "vbs", "vbe", "js", "jse", "wsf", "wsh", "ws", "wsc", "sct",
  "ps1", "psm1", "reg", "jar", "jnlp", "gadget", "xll", "appref-ms", "application",
  "settingcontent-ms", "appx", "msix", "appinstaller", "diagcab", "scf",
  "library-ms", "searchconnector-ms", "iso", "img", "vhd", "vhdx",
  // Linux desktops.
  "desktop", "sh", "run", "appimage", "deb", "rpm", "flatpakref",
]

/// True when `name` ends in an extension from `mosaicExecutableExtensions`.
func mosaicHasExecutableExtension(_ name: String) -> Bool {
  guard let fileExtension = mosaicFileExtension(name) else { return false }
  return mosaicExecutableExtensions.contains(fileExtension)
}

/// `files.open`: the outcome dictionary, never a thrown error.
func mosaicRunFilesOpen(_ payload: Any, dialogs: MosaicFileDialogs) -> [String: Any] {
  let request = mosaicPayloadDictionary(payload)
  guard let chosen = dialogs.chooseFileToOpen(extensions: mosaicExtensions(for: request)) else {
    return mosaicCancelled()
  }
  // Not the error's own text: it can carry the full local path, and a
  // failure message is data the app sees.
  let bytes: Data
  switch mosaicReadChosenFile(chosen, limit: mosaicMaxOpenBytes) {
  case .bytes(let read): bytes = read
  case .notRegular: return mosaicFailed("that is not a regular file")
  case .tooLarge:
    return mosaicFailed("the selected file is larger than \(mosaicMaxOpenBytes) bytes")
  case .unreadable: return mosaicFailed("couldn't read the selected file")
  }
  return mosaicOk([
    "name": chosen.lastPathComponent,
    "mimeType": mosaicMimeType(for: chosen),
    "bytes": bytes.base64EncodedString(),
  ])
}

/// `files.save`: the outcome dictionary, never a thrown error.
func mosaicRunFilesSave(_ payload: Any, dialogs: MosaicFileDialogs) -> [String: Any] {
  let request = mosaicPayloadDictionary(payload)
  let suggestedName = request["suggestedName"] as? String ?? ""
  guard mosaicIsPlainFileName(suggestedName) else {
    return mosaicFailed("suggestedName must be a plain file name")
  }
  guard let encoded = request["bytes"] as? String else {
    return mosaicFailed("bytes must be base64 text")
  }
  // Checked on the encoded length before decoding, so an oversized payload is
  // refused without allocating its decoded copy (4 base64 chars = 3 bytes).
  if encoded.utf8.count > (mosaicMaxSaveBytes / 3 + 1) * 4 {
    return mosaicFailed("the file is larger than \(mosaicMaxSaveBytes) bytes")
  }
  guard let bytes = Data(base64Encoded: encoded) else {
    return mosaicFailed("bytes must be base64 text")
  }
  if bytes.count > mosaicMaxSaveBytes {
    return mosaicFailed("the file is larger than \(mosaicMaxSaveBytes) bytes")
  }
  // When the app says what it is saving, the name must agree: a JSON export
  // cannot be offered as `notes.exe`.
  let extensions = mosaicExtensions(for: request)
  let suggestedExtension = mosaicFileExtension(suggestedName)
  if !extensions.isEmpty && !extensions.contains(where: { $0 == suggestedExtension }) {
    return mosaicFailed("suggestedName must end in an extension of an accepted type")
  }
  if extensions.isEmpty && mosaicHasExecutableExtension(suggestedName) {
    return mosaicFailed("suggestedName must not end in an executable extension")
  }
  guard let target = dialogs.chooseFileToSave(suggestedName: suggestedName, extensions: extensions)
  else {
    return mosaicCancelled()
  }
  return mosaicWriteReplacing(target, with: bytes)
}

/// Write `bytes` beside `target` and rename it into place, so an interrupted
/// save never leaves a half-written file where the person's old one was.
///
/// - The temporary file is created owner-only (0600) and exclusively
///   (`O_EXCL`, so it cannot be a link someone planted).
/// - It takes the permission bits (rwx only -- never setuid, setgid or
///   sticky) of the file it replaces, so saving over a private file never
///   leaves the new one readable by other users. Only from a regular file the
///   person owns: a file someone else planted does not get to choose them.
/// - Those bits are applied with `fchmod` on the open descriptor. A `chmod`
///   by path would follow a symlink swapped in after the write, and land on
///   whatever file it pointed at.
private func mosaicWriteReplacing(_ target: URL, with bytes: Data) -> [String: Any] {
  var mode: mode_t = 0o600
  var existing = stat()
  if lstat(target.path, &existing) == 0,
    (existing.st_mode & S_IFMT) == S_IFREG,
    existing.st_uid == getuid()
  {
    mode = existing.st_mode & 0o777
  }
  let directory = target.deletingLastPathComponent()
  let temporary = directory.appendingPathComponent(".mosaic-save-\(UUID().uuidString).tmp")
  let descriptor = open(temporary.path, O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW, 0o600)
  guard descriptor >= 0 else { return mosaicFailed("couldn't save the file") }
  let handle = FileHandle(fileDescriptor: descriptor, closeOnDealloc: false)
  var renamed = false
  defer {
    if !renamed { unlink(temporary.path) }
  }
  do {
    try handle.write(contentsOf: bytes)
    guard fchmod(descriptor, mode) == 0 else {
      try? handle.close()
      return mosaicFailed("couldn't save the file")
    }
    try handle.synchronize()
  } catch {
    try? handle.close()
    return mosaicFailed("couldn't save the file")
  }
  try? handle.close()
  guard rename(temporary.path, target.path) == 0 else {
    return mosaicFailed("couldn't save the file")
  }
  renamed = true
  return mosaicOk(["name": target.lastPathComponent])
}

/// Route one effect (UI87 §7.2). True when this library takes it, false when
/// it belongs to the app's handler, and nil when nobody should answer it here
/// (the host then fails an unanswered Await).
func mosaicRoutesToPlatform(_ kind: String, appKinds: Set<String>?) -> Bool? {
  if appKinds?.contains(kind) == true { return false }
  if mosaicStandardEffectKinds.contains(kind) { return true }
  if appKinds == nil { return false }
  return nil
}

/// The handler this library installs: it routes each effect by kind (UI87
/// §7.2) and answers the standard kinds itself.
final class MosaicPlatformRouter {
  // Weak, as the host's `effectHandler` documentation asks: the host holds
  // this router's closure, so a strong reference back would be a cycle that
  // keeps the Rust app handle, and its final persist, from ever running.
  private weak var host: MosaicPlatformEffectHost?
  private let appHandler: ((UInt64, String, Any, String) -> Void)?
  private let appKinds: Set<String>?
  private let dialogs: MosaicFileDialogs
  private let hasDialogs: Bool
  private let runOnUI: (@escaping () -> Void) -> Void
  // One file operation at a time (UI87 §3.1): a second request while a panel
  // is open is failed, not queued behind it. Guarded by `busyLock` because the
  // handler can run on whichever thread settled the effect.
  private var busy = false
  private let busyLock = NSLock()

  init(
    host: MosaicPlatformEffectHost,
    appHandler: ((UInt64, String, Any, String) -> Void)?,
    appKinds: Set<String>?,
    dialogs: MosaicFileDialogs,
    hasDialogs: Bool,
    runOnUI: @escaping (@escaping () -> Void) -> Void
  ) {
    self.host = host
    self.appHandler = appHandler
    self.appKinds = appKinds
    self.dialogs = dialogs
    self.hasDialogs = hasDialogs
    self.runOnUI = runOnUI
  }

  func handle(_ id: UInt64, _ kind: String, _ payload: Any, _ delivery: String) {
    switch mosaicRoutesToPlatform(kind, appKinds: appKinds) {
    case .some(false): appHandler?(id, kind, payload, delivery)
    case .none: break
    case .some(true): answerStandard(id, kind, payload, delivery)
    }
  }

  private func claim() -> Bool {
    busyLock.lock()
    defer { busyLock.unlock() }
    if busy { return false }
    busy = true
    return true
  }

  private func release() {
    busyLock.lock()
    busy = false
    busyLock.unlock()
  }

  private func answerStandard(_ id: UInt64, _ kind: String, _ payload: Any, _ delivery: String) {
    // Only an Await has someone waiting for the answer.
    guard delivery.lowercased() == "await", let host else { return }
    // No panels here (iOS, for now): answer inline, which the recursive lock
    // allows, instead of pretending the person cancelled.
    guard hasDialogs else {
      _ = host.completeEffect(id, mosaicFailed("\(kind) is not available on this platform yet"))
      return
    }
    guard claim() else {
      _ = host.completeEffect(id, mosaicFailed("another file operation is in progress"))
      return
    }
    // Ownership first. False means the runtime is not waiting on this id, and
    // the right move is to open no panel at all.
    guard host.deferEffect(id) else {
      release()
      return
    }
    let dialogs = self.dialogs
    runOnUI { [weak self, weak host] in
      let outcome = kind == "files.open"
        ? mosaicRunFilesOpen(payload, dialogs: dialogs)
        : mosaicRunFilesSave(payload, dialogs: dialogs)
      self?.release()
      _ = host?.completeEffect(id, outcome)
    }
  }
}

// Hosts that already carry a router, held weakly so a closed host is not kept
// alive by this table. Installing twice would stack one router inside another.
private let mosaicRoutedHosts = NSHashTable<AnyObject>.weakObjects()
private let mosaicRoutedHostsLock = NSLock()

/// Install the platform library on `host`, wrapping whatever handler the app
/// installed. `appKinds` is the app's `[host_effects]` `kinds`, or nil when it
/// declared none. `dialogs`, `hasDialogs` and `runOnUI` are replaceable for
/// tests. Idempotent per host: a second call changes nothing.
///
/// The router is kept alive by the closure the host holds; the router holds
/// the host weakly, so no cycle forms.
func installMosaicPlatformEffects(
  _ host: MosaicPlatformEffectHost,
  appKinds: Set<String>?,
  dialogs: MosaicFileDialogs = MosaicSystemFileDialogs(),
  hasDialogs: Bool = mosaicPlatformHasFileDialogs,
  runOnUI: @escaping (@escaping () -> Void) -> Void = { DispatchQueue.main.async(execute: $0) }
) {
  mosaicRoutedHostsLock.lock()
  defer { mosaicRoutedHostsLock.unlock() }
  if mosaicRoutedHosts.contains(host) { return }
  mosaicRoutedHosts.add(host)
  let router = MosaicPlatformRouter(
    host: host,
    appHandler: host.effectHandler,
    appKinds: appKinds,
    dialogs: dialogs,
    hasDialogs: hasDialogs,
    runOnUI: runOnUI
  )
  host.effectHandler = { id, kind, payload, delivery in
    router.handle(id, kind, payload, delivery)
  }
}
